UPDATE product
name = #{name}, price = #{price}, stock = #{stock}, category = #{category}, image_url = #{imageUrl}, description = #{description},
WHERE id = #{id}

mapper.select:
SELECT * FROM product

    is_deleted = 0
    AND category_id = #{categoryId}
    AND brand_id = #{brandId}
    AND status = #{status}

        AND (name LIKE CONCAT('%', #{keyword}, '%')
        OR description LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY id DESC
